window.MYSTERY_STORIES = [
  {
    id:'mascot', band:'3-5', number:'01', title:'The Missing Class Mascot', subtitle:'Where did Pip the Puffin go?', time:'8 min', keyUse:'Explain', objective:'Describe what you observe, separate an observation from a guess, and explain a conclusion with evidence.', vocabulary:['display','observe','inference'], setting:'Classroom at celebration time',
    scenes:[
      {title:'The empty place',art:'classroom',text:'The class celebration begins in twenty minutes. The blue puffin mascot, Pip, is missing from the reading rug.',dialogue:[['Maya','The rug is empty. I can see one blue feather beside the bookshelf.'],['Leo','Maybe someone took Pip!'],['Zara','That is a guess. First, let’s say exactly what we can see.']],activity:{type:'sort',domain:'reading',prompt:'Which sentence is an observation?',options:['The rug is empty.','Someone took Pip.'],answer:0,feedback:'An observation tells what a person can see. The empty rug is visible; who moved Pip is not known yet.',frame:'I observe ___. I do not know ___ yet.',evidence:'Select an observation rather than a guess.'}},
      {title:'A feather trail',art:'hallway',text:'Maya follows two blue feathers. They stop at the art-room doorway. The door is open, and a paper sign says “Wet paint.”',dialogue:[['Maya','Two feathers lead to the art room.'],['Leo','So the art teacher hid Pip in there!'],['Zara','We have a trail, but not the whole answer. Let’s look safely from the doorway.']],activity:{type:'clue',domain:'reading',prompt:'Inspect the clues. Which detail do you notice?',clues:[{label:'Two blue feathers',detail:'The feathers make a short trail from the rug toward the art room.'},{label:'Wet-paint sign',detail:'The sign tells visitors to stay out while artwork dries.'}],answer:0,feedback:'A trail points toward a place. It does not yet tell us who moved the mascot or why.',evidence:'Open a clue and name the visible detail.'}},
      {title:'Ask before entering',art:'artroom',text:'The friends stay outside. Through the window, they see a paper beak on a drying rack and a blue scarf draped nearby.',dialogue:[['Zara','Let’s ask Ms. Bell before we go in.'],['Maya','Ms. Bell, did you see Pip?'],['Ms. Bell','I moved the mascot away from the wet paint. I can explain when the class is ready.']],activity:{type:'dialogue',domain:'speaking',prompt:'Choose a respectful question for Ms. Bell.',options:['Did you move Pip to keep it safe?','Why did you take our mascot?','Can I touch the wet paint?'],answer:0,feedback:'A calm question invites information without treating a guess as fact.',frame:'Did you ___ because ___?',evidence:'Ask a question that checks an idea respectfully.'}},
      {title:'Put the moments in order',art:'classroom',text:'Ms. Bell tells the class: first Pip sat beside the art table, then the paint began to drip, and then she moved Pip to the dry shelf.',dialogue:[['Leo','The order explains the feathers.'],['Maya','Pip was moved after the paint started dripping.'],['Zara','Let’s put the events in order before we decide.']],activity:{type:'timeline',domain:'listening',prompt:'Put these events in the order Ms. Bell described.',items:['Ms. Bell moved Pip to the dry shelf.','Pip sat beside the art table.','Paint began to drip.'],order:[1,2,0],feedback:'The sequence is: Pip by the table, paint starts to drip, Ms. Bell moves Pip.',evidence:'Arrange three reported events in sequence.'}},
      {title:'Check the evidence',art:'artroom',text:'The paper beak is part of the class art display. Pip is safe on the high dry shelf, away from paint.',dialogue:[['Maya','We saw the feather trail and the wet-paint sign.'],['Leo','Ms. Bell said she moved Pip to keep it dry.'],['Zara','Those clues support a careful explanation.']],activity:{type:'connect',domain:'writing',prompt:'Which evidence best supports the claim that Pip was moved to stay dry?',options:['The wet-paint sign and Ms. Bell’s report','The celebration starts in twenty minutes'],answer:0,feedback:'Use the clue that connects directly to the claim. The sign shows a paint risk, and Ms. Bell explains the move.',frame:'I think ___ because ___. The clue ___ supports my idea.',evidence:'Connect a claim to relevant evidence.'}},
      {title:'A safe return',art:'classroom',text:'Ms. Bell brings Pip back after the paint dries. The class adds a small “Please keep me dry” tag to the display stand.',dialogue:[['Leo','Pip is back, and no one stole it.'],['Maya','We observed a trail, asked a question, and checked the explanation.'],['Zara','That is how a mystery becomes a supported answer.']],activity:{type:'writing',domain:'writing',prompt:'Write two or three sentences explaining where Pip went and how the clues helped.',frame:'At first, I observed ___. Then I learned ___. I conclude ___ because ___.',criteria:['Name what happened','Use one clue','Connect the clue to the conclusion'],evidence:'Write a short evidence-based explanation.'}}
    ],
    teacher:{cluster:'Grades 2–3 (Grade 3) / Grades 4–5',domains:['Listening','Speaking','Reading','Writing'],followup:'Invite partners to describe one object using only visible details before they make an inference.'}
  },
  {
    id:'lunchbox',band:'3-5',number:'02',title:'The Lunchbox Mix-Up',subtitle:'Two blue boxes, one careful comparison',time:'8 min',keyUse:'Narrate',objective:'Compare details, ask a clarifying question, and use a sequence to explain how two lunchboxes were exchanged.',vocabulary:['compare','label','exchange'],setting:'Busy cafeteria',
    scenes:[
      {title:'The wrong lunch',art:'cafeteria',text:'At lunch, Noor opens a blue lunchbox. Inside is a cheese sandwich. Noor packed apple slices and a sunflower-butter sandwich.',dialogue:[['Maya','Two lunchboxes are blue. Noor’s lunch does not match.'],['Leo','They must be identical.'],['Zara','Let’s compare details before we decide what happened.']],activity:{type:'clue',domain:'reading',prompt:'Inspect each lunchbox label.',clues:[{label:'Noor’s star sticker',detail:'Noor’s box has a yellow star sticker beside the handle.'},{label:'Plain blue lid',detail:'The other lunchbox has no sticker on its lid.'}],answer:0,feedback:'The star sticker is a visible detail that can help tell the boxes apart.',evidence:'Inspect and report a distinguishing detail.'}},
      {title:'Compare the contents',art:'cafeteria',text:'Noor checks the lunch list tucked into a pocket. The list says “apple slices, sunflower spread.”',dialogue:[['Maya','The list and the lunch do not match.'],['Leo','Maybe Noor forgot what was packed.'],['Noor','I remember putting apple slices in this morning. Can we check the other box?']],activity:{type:'sort',domain:'reading',prompt:'Which detail is different from Noor’s lunch list?',options:['A cheese sandwich','A blue lunchbox'],answer:0,feedback:'The lunch list names apple slices and sunflower spread. The cheese sandwich is a different item.',frame:'Both boxes are ___. Only this box has ___.',evidence:'Compare a written list with an object.'}},
      {title:'Ask a clear question',art:'cafeteria',text:'Across the table, Eli looks worried. Their lunchbox has a yellow star sticker, but Eli’s name card is tucked inside.',dialogue:[['Zara','Eli, may we ask about the star sticker?'],['Eli','My little sister put it there. I thought it was my box.'],['Maya','Could we compare the name cards together?']],activity:{type:'dialogue',domain:'speaking',prompt:'Choose a clarifying question.',options:['Can we check the name card inside?','Why did you steal that lunch?','Do you always mix things up?'],answer:0,feedback:'A clarifying question checks information without blaming someone.',frame:'Could we check ___ so we can ___?',evidence:'Use a respectful question to clarify.'}},
      {title:'Rebuild the mix-up',art:'cafeteria',text:'Both boxes were blue. Eli’s sister added a star to Eli’s box. Noor and Eli picked up the nearest blue box in the lunch line.',dialogue:[['Leo','The boxes looked alike, and the star made Eli think it was theirs.'],['Noor','We both chose the nearest blue one.'],['Zara','That sequence makes sense of the mix-up.']],activity:{type:'timeline',domain:'listening',prompt:'Arrange what happened.',items:['Noor and Eli picked up the nearest blue boxes.','Eli’s sister placed a star sticker on Eli’s box.','The two lunchboxes sat together in the line.'],order:[1,2,0],feedback:'First the sticker was added, then the similar boxes were together, and then each student picked up the nearest one.',evidence:'Sequence events from two accounts.'}},
      {title:'Match the evidence',art:'cafeteria',text:'Eli finds the name card inside Noor’s lunch. Noor finds Eli’s name card in the other box. The contents match each student’s written lunch list.',dialogue:[['Maya','The name cards and lunch lists agree.'],['Leo','That is stronger evidence than guessing from the color.'],['Zara','Let’s explain how the exchange happened.']],activity:{type:'connect',domain:'writing',prompt:'Which evidence supports an accidental exchange?',options:['The name cards are inside the opposite boxes','The cafeteria has blue tables'],answer:0,feedback:'The name cards directly show that the boxes were switched. The table color does not explain the mix-up.',frame:'The boxes were exchanged because ___. I know this because ___.',evidence:'Select evidence that supports a conclusion.'}},
      {title:'Lunch is back on track',art:'cafeteria',text:'Noor and Eli exchange the boxes. They agree to check the name card before leaving the lunch line next time.',dialogue:[['Noor','My apple slices are here. Thanks for asking first.'],['Eli','And I have my sandwich. The star was a helpful clue, but not the whole answer.'],['Maya','We compared the labels, lists, and events. Mystery solved.']],activity:{type:'writing',domain:'writing',prompt:'Explain the lunchbox mix-up in two or three sentences.',frame:'The boxes looked alike because ___. Then ___. We know they were switched because ___.',criteria:['Describe one similarity','Describe one difference','Use evidence to explain the mix-up'],evidence:'Write a compare-and-explain response.'}}
    ],teacher:{cluster:'Grades 2–3 (Grade 3) / Grades 4–5',domains:['Reading','Speaking','Listening','Writing'],followup:'Use two familiar classroom objects and have students compare a shared feature and a distinguishing feature.'}
  },
  {
    id:'sound',band:'3-5',number:'03',title:'The Mystery Sound',subtitle:'A clatter after the last bell',time:'9 min',keyUse:'Explain',objective:'Listen for details, sequence events, and explain a cause using sound evidence.',vocabulary:['echo','source','sequence'],setting:'School hallway after dismissal',
    scenes:[
      {title:'Clang—roll—tap',art:'hallway',text:'After dismissal, a clanging sound comes from the quiet hallway. The sound ends with three quick taps.',dialogue:[['Leo','I heard a clang, then something rolled, then tap-tap-tap.'],['Maya','It came from near the gym doors.'],['Zara','Let’s listen carefully and write the order of the sounds.']],activity:{type:'listening',domain:'listening',prompt:'Listen to the sound pattern, then choose what came last.',audio:'Clang. Roll. Tap, tap, tap.',options:['Three taps','A roll','A clang'],answer:0,feedback:'The sound pattern ends with three taps. Listening for order gives us useful evidence.',evidence:'Identify the final sound in an oral sequence.'}},
      {title:'A mark on the floor',art:'hallway',text:'Near the gym, the friends see a short silver streak on the tile. A foam ball rests beside a closed equipment cart.',dialogue:[['Maya','The streak ends near the cart.'],['Leo','The cart made the sound.'],['Zara','Maybe. We need another clue before we name the cause.']],activity:{type:'clue',domain:'reading',prompt:'Inspect two details from the hallway.',clues:[{label:'Silver streak',detail:'A short shiny line on the tile points toward the equipment cart.'},{label:'Foam ball',detail:'The ball is soft and rests beside the cart wheel.'}],answer:1,feedback:'The soft ball can make the repeated taps if it bumps a surface. The streak shows a path, not a sound by itself.',evidence:'Describe a clue and what it may suggest.'}},
      {title:'Listen from a safe place',art:'gym',text:'The gym door is open. From the doorway, they hear a small wheel rattling and a ball bouncing once against the cart.',dialogue:[['Zara','We can listen from here. No need to move anything.'],['Leo','The rattle sounds like a loose wheel.'],['Maya','And one bounce could make those taps echo down the hall.']],activity:{type:'dialogue',domain:'listening',prompt:'Which detail did Maya report hearing?',options:['One bounce against the cart','A door slamming twice','A whistle from the playground'],answer:0,feedback:'Maya reports one bounce. A careful report keeps the detail separate from the explanation.',evidence:'Match an oral report to its detail.'}},
      {title:'Put the sounds in order',art:'gym',text:'Coach Rivera explains that a ball rolled into the cart wheel. The loose wheel rattled, and the ball bounced three times in the metal tray.',dialogue:[['Coach Rivera','First the ball rolled, then it hit the wheel, and then it bounced in the tray.'],['Maya','That matches what we heard.'],['Zara','Let’s check the event order.']],activity:{type:'timeline',domain:'listening',prompt:'Sequence the events described by Coach Rivera.',items:['The ball bounced in the metal tray.','The ball rolled into a cart wheel.','The loose wheel rattled.'],order:[1,2,0],feedback:'The ball rolled into the wheel, the wheel rattled, and the ball bounced in the tray.',evidence:'Sequence the cause and resulting sounds.'}},
      {title:'Connect sound and cause',art:'gym',text:'The cart wheel is loose. A ball rolling into it causes the rattle. The metal tray makes the taps louder.',dialogue:[['Leo','So the cart caused every sound?'],['Maya','The ball started the chain, the loose wheel rattled, and the tray echoed the taps.'],['Zara','That explanation connects the clues.']],activity:{type:'connect',domain:'writing',prompt:'Choose the explanation that connects the evidence.',options:['A rolling ball hit the loose wheel; then it bounced in the metal tray.','A loud sound came from somewhere in school.'],answer:0,feedback:'A strong explanation names the cause and connects it to the sounds heard in order.',frame:'First ___, so ___. Then ___.',evidence:'Connect an observed cause to sound evidence.'}},
      {title:'A quiet fix',art:'gym',text:'Coach tightens the wheel and moves the foam balls into a bin. The next afternoon, the hallway stays quiet.',dialogue:[['Maya','We heard a sequence, checked the place, and asked Coach.'],['Leo','The loose wheel and bouncing ball explain the sound.'],['Zara','We used listening and evidence instead of choosing the scariest guess.']],activity:{type:'writing',domain:'writing',prompt:'Write a short explanation of the mystery sound. Include the sound order and its cause.',frame:'I heard ___. The sounds happened when ___. The clue ___ supports my explanation.',criteria:['Include two sound details','Name the cause','Connect a clue to the cause'],evidence:'Explain a cause and effect using oral details.'}}
    ],teacher:{cluster:'Grades 2–3 (Grade 3) / Grades 4–5',domains:['Listening','Reading','Speaking','Writing'],followup:'Play a familiar, non-startling classroom sound twice and invite learners to record sound details before naming a source.'}
  },
  {
    id:'messages',band:'3-5',number:'04',title:'The Mixed-Up Messages',subtitle:'Two notes point to two different places',time:'9 min',keyUse:'Inform',objective:'Read for specific details, clarify a confusing message, and explain how a small word changed the plan.',vocabulary:['message','detail','clarify'],setting:'School library and courtyard',
    scenes:[
      {title:'Two meeting places',art:'library',text:'A note on the classroom door says “Meet by the library at 3.” A second note says “Meet in the library at 3.” The club is waiting in two places.',dialogue:[['Maya','One note says by the library. The other says in the library.'],['Leo','Those sound almost the same.'],['Zara','The small word changes the place. Let’s read each message closely.']],activity:{type:'sort',domain:'reading',prompt:'Which note says to meet inside?',options:['Meet by the library at 3.','Meet in the library at 3.'],answer:1,feedback:'“In the library” means inside. “By the library” means near it, often outside.',frame:'The word ___ tells us ___.',evidence:'Interpret a location word in a short message.'}},
      {title:'Follow the written detail',art:'courtyard',text:'The club map shows a bench beside the library steps and a reading circle inside the library. A new note has a small arrow pointing outdoors.',dialogue:[['Leo','The arrow points to the bench.'],['Maya','The note says “by,” and the map shows the bench outside.'],['Zara','Those details agree.']],activity:{type:'clue',domain:'reading',prompt:'Inspect the map clues.',clues:[{label:'Bench marker',detail:'The bench marker is outside beside the library steps.'},{label:'Reading-circle marker',detail:'The circle is drawn inside the library walls.'}],answer:0,feedback:'The bench marker is outside, so it fits a meeting “by” the library.',evidence:'Use a map detail to clarify a written direction.'}},
      {title:'Ask for clarification',art:'library',text:'Mr. Chen wrote the first note. He is setting up chairs inside and did not see the second note.',dialogue:[['Maya','Mr. Chen, did you mean for us to meet by the library or in it?'],['Mr. Chen','By the library. I will add “outside, by the bench” so it is clearer.'],['Zara','That question helped us confirm the meaning.']],activity:{type:'dialogue',domain:'speaking',prompt:'Choose a question that clarifies the plan.',options:['Did you mean outside by the bench?','Why did you make a bad note?','Should we all leave?'],answer:0,feedback:'The question names both possible meanings and asks the writer to confirm.',frame:'Did you mean ___ or ___?',evidence:'Ask a focused question about a message.'}},
      {title:'Compare the notes',art:'library',text:'The first note says “by.” The second note says “in.” Both say 3 o’clock. Only the place word changed.',dialogue:[['Leo','The time is the same in both notes.'],['Maya','The place word is different.'],['Zara','Let’s keep the shared detail and fix the confusing one.']],activity:{type:'connect',domain:'reading',prompt:'Which detail caused the two groups to wait in different places?',options:['The words “by” and “in”','The time 3 o’clock'],answer:0,feedback:'The shared time did not cause the split. The different location words did.',evidence:'Compare two short sources and locate a contradiction.'}},
      {title:'Make a clear timeline',art:'courtyard',text:'At 2:45, Mr. Chen posts “by the library.” At 2:50, another student posts “in the library.” At 3:00, the club splits up.',dialogue:[['Maya','The second message came later, so some students followed it.'],['Leo','Both notes looked current.'],['Zara','The posting order helps us understand the confusion.']],activity:{type:'timeline',domain:'reading',prompt:'Arrange the message events by time.',items:['The club splits up.','Mr. Chen posts “by the library.”','A second student posts “in the library.”'],order:[1,2,0],feedback:'First the “by” note was posted at 2:45, then the “in” note at 2:50, and then the club split at 3:00.',evidence:'Sequence messages and a resulting event.'}},
      {title:'One message everyone can use',art:'courtyard',text:'The club updates the plan: “At 3:00, meet outside on the bench by the library steps.” Everyone finds the group.',dialogue:[['Leo','Now the place is clear.'],['Maya','We compared the written details and checked with the writer.'],['Zara','Good messages make the important details easy to find.']],activity:{type:'writing',domain:'writing',prompt:'Write a clear meeting message. Include a time and a specific place.',frame:'At ___, meet ___ at/by ___.',criteria:['Include a time','Name an exact place','Use words that remove the two meanings'],evidence:'Revise a message to make its location clear.'}}
    ],teacher:{cluster:'Grades 2–3 (Grade 3) / Grades 4–5',domains:['Reading','Speaking','Writing','Listening'],followup:'Ask learners to revise a real classroom direction by adding a landmark and a precise location word.'}
  },
  {
    id:'garden',band:'3-5',number:'05',title:'The Garden Surprise',subtitle:'What changed the school garden overnight?',time:'9 min',keyUse:'Explain',objective:'Compare before-and-after observations, make a cautious prediction, and support a conclusion with evidence.',vocabulary:['compare','change','evidence'],setting:'School garden after a windy night',
    scenes:[
      {title:'A changed garden',art:'garden',text:'Yesterday the bean trellis stood straight. This morning, one side leans and several leaves are on the path.',dialogue:[['Maya','The trellis leans toward the path.'],['Leo','A big animal must have pushed it.'],['Zara','Let’s compare the garden details before we settle on a cause.']],activity:{type:'sort',domain:'reading',prompt:'Which sentence describes what can be seen?',options:['Several leaves are on the path.','An animal pushed the trellis.'],answer:0,feedback:'Leaves on the path are visible. The animal is only a possible explanation so far.',frame:'I can see ___. I think ___ may have happened.',evidence:'Distinguish a visible change from a proposed cause.'}},
      {title:'Compare yesterday and today',art:'garden',text:'The garden photo from yesterday shows a straight trellis. The new photo shows one loose stake and a wet path.',dialogue:[['Maya','Yesterday the stake was in the soil.'],['Leo','Today it is tilted.'],['Zara','The wet path is another clue. What could make the soil softer?']],activity:{type:'clue',domain:'reading',prompt:'Inspect the before-and-after evidence.',clues:[{label:'Yesterday’s photo',detail:'The trellis is upright, and the soil around the stake looks dry.'},{label:'Today’s photo',detail:'The stake leans, and the soil looks wet after overnight rain.'}],answer:1,feedback:'The new photo shows wet soil and a leaning stake. These changes may be connected.',evidence:'Name a change across two pictures.'}},
      {title:'Make a careful prediction',art:'garden',text:'A rain gauge holds two centimeters of water. A gusty-weather notice is posted on the classroom board.',dialogue:[['Leo','Maybe the wind pushed the trellis while the rain softened the soil.'],['Maya','That could explain both clues.'],['Zara','Let’s ask Ms. Green what she saw before we decide.']],activity:{type:'branch',domain:'speaking',prompt:'Choose what the team should check next.',options:[{label:'Ask the gardener what happened overnight.',result:'Ms. Green confirms she heard wind and checked the garden after rain.'},{label:'Blame an animal without checking.',result:'The team has no evidence for an animal. Zara suggests checking the weather and asking Ms. Green.'}],feedback:'The first choice checks a source. The second is still a guess, so the case remains open.',evidence:'Choose an investigative step that can gather evidence.'}},
      {title:'Hear the gardener’s account',art:'garden',text:'Ms. Green says rain softened the soil. A strong gust leaned the trellis, and she placed a small support stake before leaving.',dialogue:[['Ms. Green','I saw the trellis after the storm. The beans were still attached.'],['Maya','So the wind leaned it, and the soft soil let the stake move.'],['Zara','Let’s put those events in order.']],activity:{type:'timeline',domain:'listening',prompt:'Arrange the gardener’s account.',items:['A gust leaned the trellis.','Rain softened the soil.','Ms. Green added a support stake.'],order:[1,0,2],feedback:'Rain softened the soil, wind leaned the trellis, and Ms. Green added a support stake.',evidence:'Sequence reported causes and a response.'}},
      {title:'Connect the changes',art:'garden',text:'The wet soil and leaned stake match Ms. Green’s report. No animal tracks appear along the garden path.',dialogue:[['Leo','The weather clues fit better than my animal guess.'],['Maya','We have wet soil, a leaning stake, and Ms. Green’s report.'],['Zara','And no tracks to support the animal idea.']],activity:{type:'connect',domain:'writing',prompt:'Which explanation best fits the available evidence?',options:['Rain softened the soil; wind leaned the trellis.','An animal moved the trellis, though no tracks were found.'],answer:0,feedback:'The weather report and the wet soil support the first explanation. The animal idea has no matching evidence.',frame:'I conclude ___ because ___. The clue ___ supports this.',evidence:'Compare two explanations and choose the better-supported one.'}},
      {title:'A stronger garden',art:'garden',text:'Ms. Green anchors the trellis with two stakes. The bean leaves remain safe, and the club adds a weather note to the garden log.',dialogue:[['Maya','We compared the photos and asked someone who saw the garden.'],['Leo','The rain and wind explain the change.'],['Zara','We can support a conclusion and still say what evidence would change our minds.']],activity:{type:'writing',domain:'writing',prompt:'Explain what changed the garden and use two details as evidence.',frame:'Before, ___. After the storm, ___. I conclude ___ because ___ and ___.',criteria:['Compare before and after','Use two evidence details','Explain how they support the conclusion'],evidence:'Write a conclusion with evidence.'}}
    ],teacher:{cluster:'Grades 2–3 (Grade 3) / Grades 4–5',domains:['Reading','Speaking','Listening','Writing'],followup:'Show a change in a familiar environment and ask students to list observations before offering causes.'}
  },
  {
    id:'challenge',band:'3-5',number:'06',title:'The Great Mystery Club Challenge',subtitle:'A school-wide case with four kinds of clues',time:'11 min',keyUse:'Argue',objective:'Combine observations, interviews, written clues, and event order to narrate and defend a conclusion.',vocabulary:['source','sequence','support'],setting:'School celebration challenge',
    scenes:[
      {title:'The missing welcome banner',art:'gym',text:'Before the school showcase, the welcome banner disappears from the gym. A paper star, a note, and a faint blue paint mark remain.',dialogue:[['Maya','I see a star by the stage and blue paint near the side door.'],['Leo','Someone took the banner outside.'],['Zara','That is one theory. We need to compare the clues and sources.']],activity:{type:'sort',domain:'reading',prompt:'Which detail is an observation?',options:['A blue paint mark is by the side door.','Someone took the banner outside.'],answer:0,feedback:'The paint mark is observable. Who moved the banner is still a theory.',frame:'I observe ___. This may suggest ___, but I need to check.',evidence:'Separate observation from inference.'}},
      {title:'Read the setup note',art:'library',text:'A note on the stage says, “Move the welcome banner after the lights test. Keep it flat.” The note is signed “R.”',dialogue:[['Maya','The note says to move the banner after the lights test.'],['Leo','R could be Riley from the stage crew.'],['Zara','Let’s read the whole note and ask before we decide.']],activity:{type:'clue',domain:'reading',prompt:'Inspect the written clue.',clues:[{label:'Stage note',detail:'It says to move the banner after the lights test and keep it flat.'},{label:'Initial R',detail:'The note is signed with one letter. Several people at school have names beginning with R.'}],answer:0,feedback:'The instruction gives a reason and a condition. One initial alone does not identify the writer.',evidence:'Read a note and distinguish its detail from an unsupported identification.'}},
      {title:'Listen to two witnesses',art:'hallway',text:'Riley heard a cart roll after the lights test. Ms. Ortiz saw the banner lying flat beside the stage storage room.',dialogue:[['Riley','After the lights test, I heard the cart roll toward storage.'],['Ms. Ortiz','I saw the banner laid flat beside the storage room.'],['Maya','Their reports agree about the time and place.']],activity:{type:'listening',domain:'listening',prompt:'Which detail appears in both reports?',audio:'Riley: I heard the cart roll after the lights test. Ms. Ortiz: I saw the banner beside storage after the lights test.',options:['The banner was near storage after the test.','The banner was hanging in the gym.'],answer:0,feedback:'Both reports connect the move to the time after the lights test and the storage area.',evidence:'Compare two oral reports for shared details.'}},
      {title:'Rebuild the event',art:'gym',text:'The crew tested the lights. Riley moved the banner flat on a cart. Ms. Ortiz checked that it was safe beside storage.',dialogue:[['Leo','The note, both accounts, and the paint mark fit the move.'],['Zara','Let’s put the events in order so we can explain the whole case.'],['Maya','We should also check what the blue mark tells us—and what it does not.']],activity:{type:'timeline',domain:'reading',prompt:'Arrange the events using the note and reports.',items:['Ms. Ortiz checked the banner by storage.','The crew tested the lights.','Riley moved the banner flat on a cart.'],order:[1,2,0],feedback:'First the crew tested the lights, then Riley moved the banner, and then Ms. Ortiz checked it by storage.',evidence:'Sequence information from written and oral sources.'}},
      {title:'Weigh the explanations',art:'hallway',text:'The banner is beside storage. A fresh blue mark is on the cart handle. The school paint table is beside the storage-room door.',dialogue:[['Maya','The paint mark could have come from the cart near the paint table.'],['Leo','So it is not proof that someone carried the banner outside.'],['Zara','Right. Which explanation uses the strongest set of clues?']],activity:{type:'connect',domain:'writing',prompt:'Connect the claim to the best evidence.',options:['The crew moved the banner after the lights test; the note, witness reports, and banner by storage support this.','Someone took the banner outside; the blue mark proves it.'],answer:0,feedback:'The note, two reports, and banner location form a consistent chain. A paint mark alone does not prove an outdoor move.',frame:'I support the claim that ___ because the note says ___ and the witnesses reported ___.',evidence:'Weigh several clues and reject an overclaim.'}},
      {title:'Present the case',art:'gym',text:'The crew returns the banner after the lights test. The mystery was a planned move so the banner would stay flat and safe—not a theft.',dialogue:[['Maya','Our conclusion uses the note and two witness reports.'],['Leo','The paint mark was a clue, but it did not prove the banner went outside.'],['Zara','A careful case explains what the evidence supports and where it stops.']],activity:{type:'writing',domain:'writing',prompt:'Write a short case report. State what happened, give two pieces of evidence, and explain how they connect.',frame:'Our conclusion is ___. First, ___. Also, ___. These details support the conclusion because ___.',criteria:['State a clear conclusion','Use two different sources','Explain why the evidence supports the claim'],evidence:'Write an evidence-based case report.'}}
    ],teacher:{cluster:'Grades 2–3 (Grade 3) / Grades 4–5',domains:['Reading','Listening','Speaking','Writing'],followup:'Hold a brief case conference. Ask learners to name one clue that supports the claim and one clue that is not enough by itself.'}
  },
  {
    id:'lantern-1',band:'6-8',number:'07',title:'The Lantern in the Stacks · 1',subtitle:'The Disappearance',time:'10 min',keyUse:'Inform',objective:'Record what is observed and distinguish it from assumptions before building a theory.',vocabulary:['observation','source','assumption'],setting:'Bellweather Archive, east reading room',
    scenes:[
      {title:'The empty plinth',art:'archive',text:'At 6:10 p.m., the brass lantern is missing from its felt-lined plinth in the east reading room. The display case is locked and unbroken.',dialogue:[['Maya','The case is locked, its glass is unbroken, and the plinth is empty.'],['Leo','The night archivist must have taken it.'],['Zara','We do not have evidence for that. Let’s record observation separately from inference.']],activity:{type:'sort',domain:'reading',prompt:'Classify the statement “The display case is locked and unbroken.”',options:['Observed detail','Inference'],answer:0,feedback:'The locked, unbroken case is directly reported at the scene. It does not identify who moved the lantern.',frame:'I observed ___. I infer ___ because ___, but I still need to verify it.',evidence:'Identify one observed detail and avoid naming an unverified actor.'}},
      {title:'A warm circle',art:'archive',text:'The felt below the lantern is warm. A thin crescent of softened wax sits at the plinth edge. The room thermostat reads 19°C.',dialogue:[['Maya','The felt is warm, and there is softened wax.'],['Leo','So the lantern was here just moments ago.'],['Zara','That is plausible, but temperature and wax can have more than one cause.']],activity:{type:'clue',domain:'reading',prompt:'Inspect the scene evidence.',clues:[{label:'Warm felt',detail:'The felt beneath the missing lantern is warmer than the surrounding shelf.'},{label:'Soft wax crescent',detail:'A small wax crescent is softened; the archive room itself is cool at 19°C.'}],answer:1,feedback:'Soft wax and warm felt suggest recent heat near the plinth, but neither observation alone proves when or why the lantern moved.',evidence:'Describe the evidence and name its limits.'}},
      {title:'The locked cabinet',art:'archive',text:'The key log shows no cabinet entry between 5:30 and 6:10. A paper catalog slips from the desk, marked “east stacks / lower shelf.”',dialogue:[['Leo','The catalog could point to another lantern.'],['Maya','It says east stacks, lower shelf, but not which object.'],['Zara','Let’s photograph the page and keep its wording exact.']],activity:{type:'notebook',domain:'reading',prompt:'Choose what belongs in an evidence notebook.',options:['Catalog page reads “east stacks / lower shelf.”','The archivist hid the lantern on the lower shelf.'],answer:0,feedback:'Record what the page actually says. Do not turn a location note into a claim about who hid something.',frame:'Source: ___. It states ___. It does not yet show ___.',evidence:'Record a source without adding an assumption.'}},
      {title:'A sound from the corridor',art:'hallway',text:'A maintenance recording captures one cart wheel squeaking at 5:52, followed by a soft metal click. The microphone is outside the reading room.',dialogue:[['Maya','The recording places a cart sound in the corridor at 5:52.'],['Leo','That must be the lantern cart.'],['Zara','It could be. We need to connect the sound to another source before we identify it.']],activity:{type:'listening',domain:'listening',prompt:'Listen to the recording transcript. What sound comes after the squeak?',audio:'At 5:52: one cart wheel squeaks. A moment later, a soft metal click.',options:['A soft metal click','A second squeak','A door alarm'],answer:0,feedback:'The recording reports a soft metal click after the squeak. It does not identify the object making it.',evidence:'Report a sound detail and its time.'}},
      {title:'Two paths to check',art:'archive',text:'The catalog note points toward the lower east shelf. The corridor recording suggests a cart passed nearby. Both clues offer places to investigate; neither proves where the lantern is.',dialogue:[['Maya','We can inspect the shelf first or ask the facilities team about the cart.'],['Leo','I want to check both.'],['Zara','We will choose a first step, then keep the other lead open.']],activity:{type:'branch',domain:'speaking',prompt:'Which investigation should happen first?',options:[{label:'Inspect the lower east shelf with the archivist.',result:'The shelf holds an old lantern catalog and a dust-free rectangle, but no brass lantern. The catalog lead is useful but incomplete.'},{label:'Interview the facilities worker about the cart sound.',result:'The facilities worker confirms a supply cart passed at 5:52, but cannot identify its cargo. The sound lead narrows the timeline, not the object.'}],feedback:'Either lead adds information without deciding the case alone. The team records both as partial evidence.',evidence:'Select a path and update the case without overstating its result.'}},
      {title:'Keep the case open',art:'archive',text:'The plinth, catalog note, and corridor sound are documented. The locked case and softened wax still need explanation. The team schedules witness interviews for the next morning.',dialogue:[['Maya','We know the lantern is missing from a locked case.'],['Leo','We have a warm spot, softened wax, a shelf note, and a cart sound.'],['Zara','Those are evidence leads, not a finished answer. Tomorrow we compare accounts.']],activity:{type:'writing',domain:'writing',prompt:'Write a case note with two observations and one question for the next investigation.',frame:'I observed ___. A second observation is ___. I still need to find out ___.',criteria:['Name two observations','Keep assumptions separate','Ask a testable next question'],evidence:'Write a neutral case note.'}}
    ],teacher:{cluster:'Grades 6–8',domains:['Reading','Listening','Speaking','Writing'],followup:'Ask students to label each statement as directly observed, reported by a source, or inferred. Keep these categories distinct.'}
  },
  {
    id:'lantern-2',band:'6-8',number:'08',title:'The Lantern in the Stacks · 2',subtitle:'Conflicting Accounts',time:'10 min',keyUse:'Explain',objective:'Compare witness accounts, identify a contradiction, and preserve source and time details.',vocabulary:['account','contradiction','corroborate'],setting:'Bellweather Archive, morning interviews',
    scenes:[
      {title:'Three accounts',art:'archive',text:'At 5:45, archivist Vale says the lantern was on its plinth. At 5:58, guard Imani says the case looked empty. Volunteer Ren says a lamp glowed near the lower stacks at 6:02.',dialogue:[['Maya','Three people describe different times and places.'],['Leo','Ren saw the lantern in the lower stacks.'],['Zara','Ren saw a lamp glow. We need the exact wording before deciding it was the lantern.']],activity:{type:'sort',domain:'reading',prompt:'Which statement is reported directly by Ren?',options:['A lamp glowed near the lower stacks at 6:02.','The brass lantern was taken to the lower stacks.'],answer:0,feedback:'Ren reports seeing a lamp glow. Identifying it as the missing brass lantern is an inference.',frame:'___ reported seeing ___. This may suggest ___, but it does not prove ___.',evidence:'Preserve the source exact claim.'}},
      {title:'Compare the photograph',art:'archive',text:'A 5:50 photograph shows the lantern on its plinth. A 6:00 security still shows the plinth empty. The wall clock appears two minutes fast in both images.',dialogue:[['Maya','The lantern disappears between the photographs, but their clock may be fast.'],['Leo','Then it happened at 5:58.'],['Zara','We can estimate a window, not a precise minute, until the clock is checked.']],activity:{type:'clue',domain:'reading',prompt:'Inspect what the two images can establish.',clues:[{label:'5:50 image',detail:'The lantern is on its plinth. The wall clock reads 5:50.'},{label:'6:00 image',detail:'The plinth is empty. The wall clock reads 6:00 and is reported to run two minutes fast.'}],answer:1,feedback:'The images bracket the disappearance. Because the clock runs fast, the displayed times are not exact real times.',evidence:'Identify what a source establishes and its limitation.'}},
      {title:'Hear the two times',art:'archive',text:'Vale remembers locking the room at 5:47. Imani’s hallway log records a door chime at 5:56. The display case alarm did not activate.',dialogue:[['Vale','I locked the reading room at 5:47.'],['Imani','The door chime sounded at 5:56, but the case alarm stayed quiet.'],['Maya','The door and case provide different information.']],activity:{type:'listening',domain:'listening',prompt:'Listen to the reports. Which alarm remained quiet?',audio:'Vale locked the reading room at 5:47. Imani heard the door chime at 5:56. The display case alarm did not activate.',options:['Display case alarm','Door chime'],answer:0,feedback:'The door chime sounded; the display case alarm did not activate. That distinction matters.',evidence:'Compare two events from oral reports.'}},
      {title:'The clock mismatch',art:'archive',text:'A technician checks the wall clock and finds it runs two minutes fast. The security still is labeled 6:00; the likely real time is about 5:58.',dialogue:[['Leo','The photo and Imani’s 5:56 chime are close together.'],['Maya','But the camera clock and wall clock may differ.'],['Zara','Let’s map the timeline with an uncertainty note.']],activity:{type:'timeline',domain:'reading',prompt:'Place the events from earliest to latest. Keep the clock offset in mind.',items:['Security still shows the plinth empty (about 5:58 real time).','Vale reports locking the room at 5:47.','Door chime is logged at 5:56.'],order:[1,2,0],feedback:'Vale reports the lock at 5:47, the door chime is logged at 5:56, and the image labeled 6:00 is about 5:58 real time. The sources may overlap.',evidence:'Sequence source events while noting uncertainty.'}},
      {title:'A contradiction worth checking',art:'archive',text:'Vale recalls locking the room before 5:50. Imani’s chime suggests a door opened later. The case alarm remained quiet, so the reports do not show that the case itself opened.',dialogue:[['Maya','The accounts conflict about access to the room.'],['Leo','Maybe the door chime was a different door.'],['Zara','That is a question we can test against the log, not a reason to dismiss either witness.']],activity:{type:'connect',domain:'writing',prompt:'Which statement describes the contradiction fairly?',options:['Vale recalls locking the room; a later door chime is logged, but the case alarm stayed quiet.','Imani proves Vale lied and opened the case.'],answer:0,feedback:'The first statement reports both sources and keeps the case alarm detail. The second makes an unsupported claim about intent.',frame:'___ reported ___. However, ___ recorded ___. This does not establish ___.',evidence:'Describe conflicting sources without accusing a witness.'}},
      {title:'Questions for Chapter 3',art:'archive',text:'The team has a narrowed time window, an unverified lamp report, and a difference between room access and case access. They prepare questions about the cart and the lower stacks.',dialogue:[['Maya','We should ask who used the supply cart.'],['Leo','And check whether another lamp was in the lower stacks.'],['Zara','Then we can compare the answers with the photographs and logs.']],activity:{type:'writing',domain:'writing',prompt:'Write two neutral interview questions that could test the remaining leads.',frame:'Who can tell us ___? What record could show ___?',criteria:['Ask a question that can be answered with evidence','Use neutral wording','Connect to a remaining clue'],evidence:'Prepare testable questions for the next investigation.'}}
    ],teacher:{cluster:'Grades 6–8',domains:['Listening','Reading','Speaking','Writing'],followup:'Use a source comparison chart with “source, exact statement, time, limitation” columns.'}
  },
  {
    id:'lantern-3',band:'6-8',number:'09',title:'The Lantern in the Stacks · 3',subtitle:'The Investigation',time:'11 min',keyUse:'Argue',objective:'Investigate competing paths, revise an earlier theory, and connect each claim to corroborating evidence.',vocabulary:['corroborate','revise','alternative'],setting:'Bellweather Archive, lower stacks and service corridor',
    scenes:[
      {title:'The cart route',art:'hallway',text:'A wheel mark leads from the east reading room to the service corridor, then turns toward a locked conservation room. No mark continues toward the public exit.',dialogue:[['Maya','The mark bends toward conservation, not the exit.'],['Leo','That weakens my idea that someone carried the lantern outside.'],['Zara','A route clue can change our theory. Let’s inspect the lock record next.']],activity:{type:'clue',domain:'reading',prompt:'Inspect the route evidence.',clues:[{label:'Wheel mark',detail:'A narrow wheel mark runs from the reading room to the conservation room.'},{label:'Public exit',detail:'The floor outside the public exit is clean; no wheel track continues there.'}],answer:0,feedback:'The wheel mark supports movement toward conservation. The clean exit weakens, but does not alone rule out, an outside route.',evidence:'Revise a theory based on a route clue.'}},
      {title:'Interview the conservator',art:'archive',text:'Conservator Ellis says a cart carried a brass lamp base to the conservation room at 5:54 for a safety check. Ellis did not see the lantern shade.',dialogue:[['Ellis','I moved a brass base on the cart. The shade was wrapped separately.'],['Maya','Was the base the missing lantern?'],['Ellis','I cannot confirm that from the base alone.']],activity:{type:'dialogue',domain:'speaking',prompt:'Ask a follow-up question that checks the identity without assuming it.',options:['What record could identify the base and shade?','Why did you steal the lantern?','Did you hide it because you were worried?'],answer:0,feedback:'The best follow-up asks for a record that can verify the object identity.',frame:'What record or detail could confirm ___?',evidence:'Ask a source to verify an object identity.'}},
      {title:'Two inventory records',art:'archive',text:'The conservation ticket lists “brass lamp base, shade wrapped separately” at 5:54. The archive catalog describes the missing lantern as a brass base with a removable shade.',dialogue:[['Leo','The description is similar.'],['Maya','The ticket and catalog match the parts, but we need the serial mark.'],['Zara','Good. Similar is not the same as confirmed.']],activity:{type:'connect',domain:'reading',prompt:'Which claim is supported by both records?',options:['A brass lamp base and separate shade were moved for a safety check.','The missing lantern was definitely stolen.'],answer:0,feedback:'The ticket and catalog support a parts description and a safety move. They do not support a theft claim.',frame:'Both records support ___. They do not yet confirm ___.',evidence:'Synthesize two written sources carefully.'}},
      {title:'Check the lantern mark',art:'archive',text:'The catalog lists serial mark B-14. A photo of the base on the conservation cart shows B-14 under the handle. The shade is wrapped on the same cart.',dialogue:[['Maya','The serial mark matches the catalog.'],['Leo','And the wrapped shade is on the same cart.'],['Zara','That strongly links the conservation ticket to the missing lantern.']],activity:{type:'sort',domain:'reading',prompt:'What kind of evidence is the matching serial mark?',options:['A specific identifying detail','A general similarity'],answer:0,feedback:'A matching serial mark is more specific than color or shape. It directly links the pictured base to the catalog entry.',frame:'The ___ matches, so this source is linked to ___.',evidence:'Identify corroborating evidence.'}},
      {title:'Revisit the warm wax',art:'archive',text:'The conservation room uses a low-heat wax seal to secure a temporary shade wrap. The wax crescent on the plinth matches the conservation wax sample.',dialogue:[['Leo','I thought the warm wax meant someone used the lantern in the reading room.'],['Maya','The matching wax has another explanation: the safety wrap.'],['Zara','We can revise an inference when new evidence explains it better.']],activity:{type:'branch',domain:'speaking',prompt:'How should the team revise its explanation?',options:[{label:'The wax may have transferred during the safety wrap; compare the sample before concluding.',result:'The wax sample matches the conservation wrap. This explains the crescent without requiring the lantern to be lit in the reading room.'},{label:'Keep the first theory because the wax felt warm.',result:'Warmth alone cannot establish that the lantern was lit. Zara adds the matching wax sample as a new source to consider.'}],feedback:'The matching wax sample gives a testable alternative explanation. The warmth remains an observation, while its cause is revised.',evidence:'Revise an inference in response to corroborating evidence.'}},
      {title:'Build the evidence map',art:'archive',text:'The case remained locked. The cart route points to conservation. The 5:54 ticket and B-14 photo identify the base. The wrapped shade is on the same cart, and the wax matches its safety wrap.',dialogue:[['Maya','Each source adds a different part of the explanation.'],['Leo','The missing object was moved for a safety check, not taken through the exit.'],['Zara','Let’s test that full claim against every clue in the final chapter.']],activity:{type:'writing',domain:'writing',prompt:'Draft a claim and connect three pieces of evidence from different sources.',frame:'My current claim is ___. The ___ shows ___. The ___ also shows ___. Together, these support ___ because ___.',criteria:['Make a clear but revisable claim','Use three distinct sources','Explain how each source connects'],evidence:'Create an evidence-linked working theory.'}}
    ],teacher:{cluster:'Grades 6–8',domains:['Reading','Speaking','Writing'],followup:'Have students mark which evidence confirms identity, route, purpose, and timing. Ask them to revise one earlier inference.'}
  },
  {
    id:'lantern-4',band:'6-8',number:'10',title:'The Lantern in the Stacks · 4',subtitle:'The Final Explanation',time:'11 min',keyUse:'Argue',objective:'Evaluate competing explanations, reconstruct a timeline, and justify a conclusion while naming a limit or uncertainty.',vocabulary:['claim','corroborate','limitation'],setting:'Bellweather Archive, case conference',
    scenes:[
      {title:'Two explanations',art:'archive',text:'Theory A: someone stole the lantern through the public exit. Theory B: staff moved it to conservation for a safety check. The team reviews all sources before choosing.',dialogue:[['Maya','We should test both theories against the full evidence set.'],['Leo','Theory A explains that the lantern left its plinth.'],['Zara','But it must also explain the locked case, cart route, serial mark, and ticket.']],activity:{type:'connect',domain:'reading',prompt:'Which theory accounts for more established evidence?',options:['Staff moved the lantern to conservation for a safety check.','Someone stole the lantern through the public exit.'],answer:0,feedback:'The safety move explains the route, ticket, serial mark, wrapped shade, and wax. The theft theory lacks supporting evidence and conflicts with the clean exit.',frame:'Theory ___ fits ___ and ___. Theory ___ does not explain ___.',evidence:'Compare competing explanations against multiple clues.'}},
      {title:'Rebuild the verified timeline',art:'archive',text:'The lantern is photographed on its plinth before 5:50. After the room is secured, the conservation ticket records the cart move at 5:54. The 6:00 still—about 5:58 real time—shows the empty plinth.',dialogue:[['Maya','The photographs give us a time window.'],['Leo','The ticket records the move at 5:54.'],['Zara','We should keep the camera clock offset visible in the timeline.']],activity:{type:'timeline',domain:'reading',prompt:'Arrange the verified events and keep the image time caveat.',items:['Conservation ticket records the cart move at 5:54.','Image shows lantern on the plinth before 5:50.','Image labeled 6:00 (about 5:58 real time) shows an empty plinth.'],order:[1,0,2],feedback:'The lantern is on the plinth before 5:50, the ticket records a 5:54 move, and the later adjusted image shows the empty plinth.',evidence:'Reconstruct an evidence-based timeline with a caveat.'}},
      {title:'Test the sources',art:'archive',text:'The ticket records the purpose as a safety check. B-14 links the moved base to the catalog. The wrapped shade on the same cart matches the lantern parts list. The case alarm stayed quiet.',dialogue:[['Leo','The ticket, serial mark, and parts list connect the move to the missing lantern.'],['Maya','The quiet case alarm fits a move without opening the display case.'],['Zara','And what does the record not tell us?']],activity:{type:'listening',domain:'listening',prompt:'Listen to the evidence summary. Which detail links the base to the catalog?',audio:'The conservation photo shows serial mark B-14 beneath the handle. The catalog lists the missing lantern as B-14.',options:['The matching serial mark B-14','The 19-degree room temperature'],answer:0,feedback:'The matching B-14 mark directly links the photographed base to the catalog entry.',evidence:'Identify a corroborating detail in an oral summary.'}},
      {title:'Name the strongest claim',art:'archive',text:'The evidence supports a planned staff move to conservation for a safety check. It does not identify who placed the first wax crescent on the plinth or the exact second the lantern left.',dialogue:[['Maya','We can say why the lantern was moved and where it went.'],['Leo','We cannot claim every detail is known.'],['Zara','A strong explanation is clear about both evidence and limits.']],activity:{type:'speaking',domain:'speaking',prompt:'Rehearse a brief explanation. State which conclusion the evidence supports, cite a clue, and name one detail the records do not establish.',feedback:'A strong oral explanation states a supported claim, connects it to a clue, and keeps uncertainty visible.',frame:'The evidence supports ___. The ___ shows ___. It does not establish ___.',criteria:['State the supported safety-move conclusion','Cite a clue such as the ticket or matching serial','Name an uncertainty without overstating'],evidence:'Orally justify a conclusion with evidence and a limitation.'}},
      {title:'Present the case',art:'archive',text:'At the case conference, the team returns the lantern to its plinth after the safety check. The archive adds a sign-out record for future moves.',dialogue:[['Maya','The ticket and B-14 photo connect the lantern to conservation.'],['Leo','The cart route and wrapped shade support how it moved.'],['Zara','The evidence supports a safety move. Our timeline has a small uncertainty, and our explanation says so.']],activity:{type:'writing',domain:'writing',prompt:'Write a final explanation: state your claim, cite at least three sources, explain their connection, and name one limitation.',frame:'I conclude ___. The ___ shows ___. The ___ corroborates this because ___. The evidence does not establish ___.',criteria:['State a supported conclusion','Use three sources','Explain how evidence connects','Name a limitation or uncertainty'],evidence:'Complete a final evidence-based case report.'}}
    ],teacher:{cluster:'Grades 6–8',domains:['Reading','Listening','Speaking','Writing'],followup:'Invite students to present a 45-second case brief with claim, three sources, reasoning, and a limitation.'}
  }
];

window.ACCESS_STUDIO_TASKS = {
  '2-3': {
    listening:{title:'Listen for a detail',prompt:'Listen to two classmates describe a classroom object. Choose the detail they both mention.',audio:'Maya: The box has a star sticker. Leo: I see the yellow star beside the handle.',options:['A star sticker','A blue table'],answer:0,support:'Listen again. Look for a word both speakers repeat.',success:'Names one detail shared by both speakers.'},
    speaking:{title:'Describe a scene',prompt:'Describe one scene clue. Tell what you see, then add what you think it may mean.',frame:'I see ___. This may mean ___ because ___.',success:'Names a visible detail and connects it to an idea.'},
    reading:{title:'Read a short clue',prompt:'“Meet by the library steps at 3:00.” Where should the group meet?',options:['Outside near the steps','Inside at the reading circle'],answer:0,support:'The word “by” means near.'},
    writing:{title:'Explain a change',prompt:'Write two sentences about a change. Name what changed and give one clue that supports your idea.',frame:'Before, ___. Now, ___. I think ___ because ___.',success:'Names a change and gives a connected clue.'}
  },
  '4-5': {
    listening:{title:'Compare two reports',prompt:'Listen to two witnesses. What time detail agrees?',audio:'Riley heard a cart at 5:54. Imani saw a cart near storage at 5:54.',options:['Both reports place a cart near storage at 5:54.','Both reports say the room was locked at 6:00.'],answer:0,support:'Listen for the repeated time and place.'},
    speaking:{title:'Sequence and explain',prompt:'Explain how a clue led to an event. Include a sequence word and a cause word.',frame:'First ___. Then ___ because ___.',success:'Sequences events and links a cause to an outcome.'},
    reading:{title:'Compare sources',prompt:'A note says “move the banner after the lights test.” A witness says the cart rolled after the test. Which detail appears in both?',options:['The move happened after the lights test','The banner was taken outside'],answer:0,support:'Keep the exact shared time condition.'},
    writing:{title:'Support a conclusion',prompt:'Write a short explanation using two clues and a connecting word.',frame:'I conclude ___. The ___ shows ___. Also, ___. These clues support ___ because ___.',success:'Uses two clues and explains their connection.'}
  },
  '6-8': {
    listening:{title:'Separate statement and inference',prompt:'Listen to the report. Select the observed detail.',audio:'The camera shows an empty plinth at 6:00. The missing lantern was taken at exactly 5:58.',options:['The camera shows an empty plinth at 6:00.','The lantern was taken at exactly 5:58.'],answer:0,support:'One sentence reports the image. The other makes a precise inference.'},
    speaking:{title:'Give a case brief',prompt:'State a claim, cite two sources, connect them, and name a limitation.',frame:'I conclude ___. The ___ shows ___. The ___ supports this because ___. We cannot establish ___.',success:'Uses a claim, evidence, reasoning, and a limitation.'},
    reading:{title:'Evaluate a claim',prompt:'A photo shows serial B-14 on a base. The catalog lists the missing lantern as B-14. What claim is best supported?',options:['The photographed base matches the catalog entry.','The conservator intended to hide the lantern.'],answer:0,support:'Choose only the claim directly supported by both sources.'},
    writing:{title:'Revise an explanation',prompt:'Write an evidence-based paragraph. Include a claim, two sources, reasoning, and one uncertainty.',frame:'The strongest explanation is ___. The ___ records ___. In addition, ___ shows ___. Together, these support ___ because ___. One uncertainty is ___.',success:'Connects two sources to a claim and names one uncertainty.'}
  }
};

const ACCESS_ALTERNATES = {
  '2-3': {
    listening:{title:'Hear the event order',prompt:'Listen to the short report. What happened after the bell?',audio:'The bell rang. Then the class lined up by the door.',options:['The class lined up by the door.','The class opened lunchboxes.'],answer:0,support:'Listen for the word “then.”'},
    speaking:{title:'Retell a short event',prompt:'Tell what happened first and what happened next in a familiar classroom routine.',frame:'First ___. Next ___.',success:'Uses two events in a clear order.'},
    reading:{title:'Use a written direction',prompt:'“Place the book on the top shelf.” Where does the book go?',options:['On the highest shelf','Under the table'],answer:0,support:'Look for the word “top.”'},
    writing:{title:'Describe an object',prompt:'Write two details that help a classmate identify a classroom object.',frame:'It is ___. It has ___.',success:'Includes two details that describe the object.'}
  },
  '4-5': {
    listening:{title:'Find the reason',prompt:'Listen to the announcement. Why did the group move inside?',audio:'The rain began during recess, so the group moved to the library.',options:['Rain began during recess.','The library closed early.'],answer:0,support:'Listen for the reason after “so.”'},
    speaking:{title:'Compare two clues',prompt:'Compare a written note and a scene detail. Tell one way they agree.',frame:'The note says ___. The scene shows ___. Both suggest ___.',success:'Uses details from two sources.'},
    reading:{title:'Identify a source detail',prompt:'A report states, “The cart left the east room at 5:54.” Which detail is stated?',options:['The cart left the east room at 5:54.','The cart carried the missing lantern.'],answer:0,support:'Choose what the report says directly.'},
    writing:{title:'Explain a sequence',prompt:'Explain how two events led to an outcome. Use a sequence word and a cause word.',frame:'First ___. Then ___ because ___.',success:'Sequences events and gives a reason.'}
  },
  '6-8': {
    listening:{title:'Compare witness statements',prompt:'Which fact do both witnesses report?',audio:'Vale: The room was locked at 5:47. Imani: A door chime sounded at 5:56.',options:['Vale reports locking the room at 5:47.','Imani reports that the case alarm sounded.'],answer:0,support:'Keep each statement connected to its source.'},
    speaking:{title:'Evaluate a competing theory',prompt:'State which theory is better supported, cite two clues, and name a limitation.',frame:'Theory ___ fits ___ and ___. One limit is ___.',success:'Compares theories, cites evidence, and names uncertainty.'},
    reading:{title:'Check evidence strength',prompt:'A catalog lists serial B-14. A photograph shows B-14 on a lamp base. Which claim is best supported?',options:['The pictured base matches the catalog entry.','The conservator planned to steal the lamp.'],answer:0,support:'Choose the claim that stays closest to both sources.'},
    writing:{title:'Revise a case claim',prompt:'Improve this claim by adding a source and explaining why its detail matters: “The lantern moved.”',frame:'The ___ records ___. This supports the claim that ___ because ___.',success:'Adds a source, a specific detail, and reasoning.'}
  }
};
for (const [cluster, domains] of Object.entries(ACCESS_ALTERNATES)) for (const [domain, task] of Object.entries(domains)) window.ACCESS_STUDIO_TASKS[cluster][domain].alternate = task;
